import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { AnimatePresence, motion } from "framer-motion";
import { Activity, Bot, Check, CheckCircle2, ClipboardCopy, Download, ExternalLink, FileCheck2, GitCompare, LoaderCircle, MessageSquare, RotateCcw, ScanSearch, ShieldCheck, TriangleAlert } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { api } from "../lib/api";
import { usePersistentDraft } from "../lib/usePersistentDraft";
import { cn, formatRelative } from "../lib/utils";
import type { AssistantResponse, DiagnosticHypothesis, HttpReplayExecution, HttpReplaySpec, HypothesisTest, HypothesisTestStatus, Incident, IncidentComment, IncidentDecision, IncidentDiagnosis, IncidentPostmortem, MitigationRequest, RecoveryVerification, ReplayConfig, ReplayResult } from "../types";
import { useAuth } from "../providers/AuthProvider";
import { useTimeZone } from "../providers/TimeZoneProvider";

type WorkArea = "investigate" | "validate" | "handoff";
const areas = [
  { id: "investigate" as const, label: "Investigate", icon: ScanSearch },
  { id: "validate" as const, label: "Validate & recover", icon: Activity },
  { id: "handoff" as const, label: "Handoff", icon: FileCheck2 }
];

function StatePill({ state }: { state: DiagnosticHypothesis["state"] }) {
  const tone = state === "supported" ? "bg-success/12 text-success" : state === "disproved" ? "bg-danger/10 text-danger" : state === "contested" ? "bg-warning/12 text-warning" : "bg-elevated text-muted";
  return <span className={cn("rounded-full px-2.5 py-1 text-xs font-semibold capitalize", tone)}>{state}</span>;
}

function MutationNote({ mutation, success }: { mutation: { isPending: boolean; isSuccess: boolean; error: Error | null; reset(): void }; success: string }) {
  if (mutation.isPending) return <p role="status" className="mt-3 text-xs text-info">Saving this operational record…</p>;
  if (mutation.error) return <p role="alert" className="mt-3 text-xs text-danger">{mutation.error.message} <button className="font-semibold underline" onClick={() => mutation.reset()}>Dismiss</button></p>;
  if (mutation.isSuccess) return <p role="status" className="mt-3 text-xs text-success">{success}</p>;
  return null;
}

function HypothesisTestCard({ test, incidentId, onOpen }: { test: HypothesisTest; incidentId: string; onOpen(testId: string): void }) {
  const client = useQueryClient();
  const draft = usePersistentDraft(`replayops:${incidentId}:test:${test.id}`, test.result);
  const update = useMutation({
    mutationFn: (status: HypothesisTestStatus) => api.updateHypothesisTest(test.id, status, draft.value.trim()),
    onSuccess: (value) => {
      client.setQueryData<HypothesisTest[]>(["hypothesis-tests", incidentId], (current) => (current ?? []).map((item) => item.id === value.id ? value : item));
      void client.invalidateQueries({ queryKey: ["hypothesis-tests", incidentId] });
      void client.invalidateQueries({ queryKey: ["diagnosis", incidentId] });
      draft.clear();
      if (["supported","disproved","inconclusive"].includes(value.status)) void api.recordProductOutcome("test_completed",{incidentId,testId:value.id,status:value.status});
    }
  });
  const terminalReady = draft.value.trim().length >= 8;
  return <article id={`test-${test.id}`} className="scroll-mt-24 rounded-control bg-elevated p-4" onClick={() => onOpen(test.id)}>
    <div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-semibold">{test.title}</p><p className="mt-1 text-xs leading-5 text-muted">{test.instruction}</p></div><StatePill state={test.status === "planned" || test.status === "running" ? "untested" : test.status} /></div>
    <p className="mt-3 text-xs text-faint">Owner: {test.assignee} · {draft.savedAt ? `draft saved ${formatRelative(draft.savedAt)}` : test.status === "planned" ? "not started" : test.status.replace("_", " ")}</p>
    <textarea className="field mt-3 min-h-20 resize-y py-3 text-sm" value={draft.value} onChange={(event) => draft.setValue(event.target.value)} placeholder="Record the query, trace, metric, and what it showed…" />
    <div className="mt-3 flex flex-wrap gap-2">{test.status === "planned" && <button className="control-secondary !min-h-9" onClick={() => update.mutate("running")}>Start</button>}<button className="control-secondary !min-h-9" disabled={!terminalReady} onClick={() => update.mutate("supported")}>Supports</button><button className="control-secondary !min-h-9" disabled={!terminalReady} onClick={() => update.mutate("disproved")}>Disproves</button><button className="control-quiet !min-h-9" disabled={!terminalReady} onClick={() => update.mutate("inconclusive")}>Inconclusive</button></div>
    {!terminalReady && draft.value.length > 0 && <p className="mt-2 text-xs text-warning">Add a concrete observation before closing this test.</p>}
    <MutationNote mutation={update as never} success="Outcome saved. Diagnosis and next action were recalculated." />
  </article>;
}

function ContextualAi({ incident, hypothesis }: { incident: Incident; hypothesis?: DiagnosticHypothesis }) {
  const [response, setResponse] = useState<AssistantResponse | null>(null);
  const ask = useMutation({ mutationFn: (intent: string) => api.ask(`${intent}. Use only evidence for ${incident.code} at evidence revision ${incident.evidenceRevision ?? incident.updatedAt}. ${hypothesis ? `Current claim: ${hypothesis.claim}` : ""} State unknowns and cite exact events.`, incident.id), onSuccess: setResponse });
  return <div className="rounded-control bg-info/8 p-4">
    <div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-semibold">Contextual assistance</p><p className="mt-1 text-xs text-muted">Scoped to this incident; prompts are redacted before any external provider call.</p></div><span className="measurement-number text-xs text-muted">REV {(incident.evidenceRevision ?? incident.updatedAt).slice(0, 12)}</span></div>
    <div className="mt-3 flex flex-wrap gap-2"><button className="control-secondary !min-h-9" onClick={() => ask.mutate("Explain the observed evidence without claiming causation")}>Explain evidence</button><button className="control-secondary !min-h-9" onClick={() => ask.mutate("Challenge the current explanation with the strongest contradiction")}>Challenge</button><button className="control-secondary !min-h-9" onClick={() => ask.mutate("Propose the cheapest safe falsification test")}>Suggest next test</button><button className="control-quiet !min-h-9" onClick={() => ask.mutate("Summarize what changed in the evidence")}>Summarize changes</button></div>
    {ask.isPending && <p className="mt-3 inline-flex items-center gap-2 text-sm text-muted"><LoaderCircle className="h-4 w-4 animate-spin" />Reviewing cited evidence…</p>}
    {ask.error && <p className="mt-3 text-sm text-danger">{ask.error.message}</p>}
    {response && <div className="mt-4 border-t border-info/20 pt-4"><div className="flex items-center justify-between"><span className="text-xs font-semibold uppercase tracking-[.12em] text-info">Evidence review</span><span className="measurement-number text-xs text-muted">{response.mode}</span></div><p className="mt-2 text-sm leading-6">{response.answer}</p><div className="mt-3 flex flex-wrap gap-2">{response.citations.flatMap((citation) => citation.eventIds.map((eventId) => <a key={`${citation.incidentId}-${eventId}`} href={citation.incidentId === incident.id ? `?area=investigate&event=${eventId}#event-${eventId}` : `/incidents/${citation.incidentId}?area=investigate&event=${eventId}#event-${eventId}`} className="rounded-full bg-panel px-2.5 py-1 text-xs font-semibold text-info hover:underline">{citation.code} · source event</a>))}</div><p className="mt-2 text-xs text-muted">{response.evidenceBoundary}. Assistance cannot approve, resolve, or execute changes.</p></div>}
  </div>;
}

function InvestigationPanel({ incident, onOpenTest }: { incident: Incident; onOpenTest(testId: string): void }) {
  const client = useQueryClient();
  const diagnosis = useQuery({ queryKey: ["diagnosis", incident.id, incident.evidenceRevision], queryFn: () => api.diagnosis(incident.id) });
  const tests = useQuery({ queryKey: ["hypothesis-tests", incident.id], queryFn: () => api.hypothesisTests(incident.id) });
  const members = useQuery({ queryKey: ["team-members"], queryFn: api.teamMembers });
  const [selectedId, setSelectedId] = useState("");
  const [assignee, setAssignee] = useState(incident.owner);
  const createTest = useMutation({
    mutationFn: (hypothesis: DiagnosticHypothesis) => api.createHypothesisTest(incident.id, { hypothesisId: hypothesis.id, title: `Test: ${hypothesis.title}`, instruction: hypothesis.nextTest, assignee }),
    onSuccess: (value) => { client.setQueryData<HypothesisTest[]>(["hypothesis-tests", incident.id], (current) => [value, ...(current ?? [])]); void api.recordProductOutcome("test_started",{incidentId:incident.id,testId:value.id}); onOpenTest(value.id); }
  });
  if (diagnosis.isLoading) return <div className="flex min-h-[420px] items-center justify-center text-sm text-muted"><LoaderCircle className="mr-2 h-4 w-4 animate-spin" />Building an evidence-grounded investigation</div>;
  if (diagnosis.error) return <div className="px-6 py-14 text-center"><TriangleAlert className="mx-auto h-6 w-6 text-danger" /><h3 className="mt-3 font-semibold">Investigation summary is unavailable</h3><button className="control-secondary mt-4" onClick={() => void diagnosis.refetch()}>Retry</button></div>;
  const data = diagnosis.data as IncidentDiagnosis;
  if (!data.hypotheses.length) return <div className="px-6 py-14 text-center"><ScanSearch className="mx-auto h-7 w-7 text-faint" /><h3 className="mt-3 font-semibold">More evidence is needed</h3><p className="mx-auto mt-1 max-w-md text-sm leading-6 text-muted">ReplayOps will not invent a cause from an empty investigation. Add a symptom, change, trace, or dependency observation.</p></div>;
  const selected = data.hypotheses.find((item) => item.id === selectedId) ?? data.hypotheses[0]!;
  return <div>
    <div className="bg-ink px-5 py-5 text-panel sm:px-6"><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_auto] lg:items-end"><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-panel/60">Current explanation · {data.evidenceStatus} evidence</p><p className="mt-2 max-w-3xl text-lg font-semibold leading-7">{data.currentExplanation}</p><div className="mt-4 flex flex-wrap items-center gap-2 text-xs text-panel/70">{data.servicePath.map((service, index) => <span key={service} className="inline-flex items-center gap-2"><span className={cn("rounded-full px-2.5 py-1", index === 0 ? "bg-panel/15 text-panel" : "bg-panel/8")}>{service}</span>{index < data.servicePath.length - 1 ? "→" : null}</span>)}</div></div><div className="max-w-xs rounded-control bg-panel/10 p-3"><p className="text-xs uppercase tracking-[.12em] text-panel/60">Next useful action</p><p className="mt-1 text-sm font-semibold">{data.nextAction.label}</p><p className="mt-1 text-xs text-panel/65">{data.nextAction.reason}</p></div></div></div>
    <div className="grid lg:grid-cols-[minmax(260px,.72fr)_minmax(0,1.28fr)]">
      <div className="border-b border-line bg-rail lg:border-b-0 lg:border-r"><div className="px-5 py-4 sm:px-6"><h3 className="section-title">Explanations under test</h3><p className="mt-1 text-xs text-muted">Ordered by evidence relevance, not probability.</p></div>{data.hypotheses.map((hypothesis) => <button key={hypothesis.id} className={cn("block w-full border-t border-line px-5 py-4 text-left transition-colors sm:px-6", selected.id === hypothesis.id ? "bg-panel" : "hover:bg-elevated")} onClick={() => setSelectedId(hypothesis.id)}><div className="flex items-start gap-3"><span className={cn("measurement-number flex h-6 w-6 shrink-0 items-center justify-center rounded-full text-xs font-semibold", selected.id === hypothesis.id ? "bg-ink text-panel" : "bg-elevated text-muted")}>{hypothesis.rank}</span><div className="min-w-0 flex-1"><p className="text-sm font-semibold">{hypothesis.title}</p><div className="mt-2 flex items-center gap-2"><StatePill state={hypothesis.state} /><span className="text-xs text-muted">{hypothesis.testCount} tests</span></div></div></div></button>)}</div>
      <div className="min-w-0 p-5 sm:p-6"><div className="flex flex-wrap items-center gap-2"><p className="measurement-number text-xs uppercase tracking-[.14em] text-muted">Explanation {selected.rank}</p><StatePill state={selected.state} /></div><h3 className="mt-2 font-heading text-xl font-semibold tracking-[-.02em]">{selected.claim}</h3><p className="mt-2 text-sm text-muted">{selected.outcomeSummary}</p>
        <div className="mt-6 grid gap-5 xl:grid-cols-2"><div><h4 className="text-xs font-semibold uppercase tracking-[.12em] text-muted">Observed support</h4><ul className="mt-3 space-y-2">{selected.supportingEvidence.map((item) => <li key={item} className="flex gap-2 text-sm leading-6"><CheckCircle2 className="mt-1 h-4 w-4 shrink-0 text-success" />{item}</li>)}</ul></div><div><h4 className="text-xs font-semibold uppercase tracking-[.12em] text-muted">Contradictions / unknowns</h4><ul className="mt-3 space-y-2">{selected.conflictingEvidence.map((item) => <li key={item} className="flex gap-2 text-sm leading-6"><TriangleAlert className="mt-1 h-4 w-4 shrink-0 text-warning" />{item}</li>)}</ul></div></div>
        <div className="mt-6 border-y border-line py-5"><p className="text-xs font-semibold uppercase tracking-[.12em] text-muted">Next falsification test</p><p className="mt-2 text-sm font-semibold leading-6">{selected.nextTest}</p><div className="mt-4 flex flex-col gap-2 sm:flex-row"><select className="field sm:max-w-64" value={assignee} onChange={(event) => setAssignee(event.target.value)}>{members.data?.map((member) => <option key={member.userId} value={member.email}>{member.displayName} · {member.role}</option>)}{!members.data?.length && <option>{incident.owner}</option>}</select><button className="control-primary" onClick={() => createTest.mutate(selected)} disabled={createTest.isPending || selected.state === "disproved"}>Assign test</button></div><MutationNote mutation={createTest as never} success="Test assigned and added to investigation history." /></div>
        <div className="mt-6"><ContextualAi incident={incident} hypothesis={selected} /></div>
      </div>
    </div>
    <div className="grid border-t border-line xl:grid-cols-[.8fr_1.2fr]"><section className="border-b border-line p-5 xl:border-b-0 xl:border-r sm:p-6"><h3 className="section-title">Missing evidence</h3><ul className="mt-3 space-y-2">{data.evidenceGaps.map((gap) => <li key={gap} className="flex gap-2 text-sm leading-5 text-muted"><TriangleAlert className="mt-0.5 h-4 w-4 shrink-0 text-warning" />{gap}</li>)}</ul></section><section className="p-5 sm:p-6"><h3 className="section-title">Tests and observations</h3><div className="mt-3 grid gap-3 xl:grid-cols-2">{tests.data?.map((test) => <HypothesisTestCard key={test.id} test={test} incidentId={incident.id} onOpen={onOpenTest} />)}{tests.data && !tests.data.length && <p className="text-sm leading-6 text-muted">Assign the next test above. Outcomes become part of the explanation history and handoff.</p>}</div></section></div>
  </div>;
}

function ScenarioEstimate({ incident }: { incident: Incident }) {
  const client = useQueryClient();
  const { user } = useAuth();
  const [config, setConfig] = useState<ReplayConfig>({ retryCeiling: 1, concurrencyCap: 18, timeoutMs: 1800 });
  const [selectedId, setSelectedId] = useState("");
  const history = useQuery({ queryKey: ["replays", incident.id], queryFn: () => api.replays(incident.id) });
  const approvals = useQuery({ queryKey: ["mitigations", incident.id], queryFn: () => api.mitigations(incident.id) });
  const workspace = useQuery({ queryKey: ["workspace"], queryFn: api.workspace });
  const selected = history.data?.find((item) => item.id === selectedId) ?? history.data?.[0] ?? null;
  const dirty = selected ? JSON.stringify(config) !== JSON.stringify(selected.config) : true;
  const stale = selected ? selected.evidenceVersion !== (incident.evidenceRevision ?? incident.updatedAt) : false;
  useEffect(() => { if (history.data?.[0] && !selectedId) { setSelectedId(history.data[0].id); setConfig(history.data[0].config); } }, [history.data, selectedId]);
  const run = useMutation({ mutationFn: () => api.runReplay(incident.id, config), onSuccess: (value) => { client.setQueryData<ReplayResult[]>(["replays", incident.id], (current) => [value, ...(current ?? [])]); setSelectedId(value.id); } });
  const requestApproval = useMutation({ mutationFn: () => { if (!selected) throw new Error("Save a scenario estimate first."); return api.requestMitigation(incident.id, { replayRunId: selected.id, title: `Review ${incident.service} control candidate`, action: `Set retry ceiling ${selected.config.retryCeiling}, concurrency cap ${selected.config.concurrencyCap}, timeout ${selected.config.timeoutMs}ms for a bounded canary.`,currentValue:"Confirm current production values before execution",proposedValue:`retry=${selected.config.retryCeiling}, concurrency=${selected.config.concurrencyCap}, timeout=${selected.config.timeoutMs}ms`,blastRadius:`Canary only for ${incident.service} in ${incident.environment??"unknown environment"}; no other environment`,changeOwner:user?.email??incident.owner,observationMinutes:15, rollbackPlan: "Restore the confirmed prior values immediately if the declared recovery metric worsens." }); }, onSuccess: (value) => { client.setQueryData<MitigationRequest[]>(["mitigations", incident.id], (current) => [value, ...(current ?? [])]); void client.invalidateQueries({ queryKey:["notifications"] }); void client.invalidateQueries({ queryKey:["audit"] }); } });
  const review = useMutation({ mutationFn: ({ id, status }: { id: string; status: "approved" | "rejected" }) => api.reviewMitigation(id, status), onSuccess: (value) => { client.setQueryData<MitigationRequest[]>(["mitigations", incident.id], (current) => (current ?? []).map((item) => item.id === value.id ? value : item)); void client.invalidateQueries({ queryKey:["notifications"] }); void client.invalidateQueries({ queryKey:["audit"] }); } });
  const set = (key: keyof ReplayConfig, value: number) => setConfig((current) => ({ ...current, [key]: value }));
  return <section className="grid xl:grid-cols-[minmax(310px,.72fr)_minmax(0,1.28fr)]"><div className="border-b border-line bg-rail p-5 sm:p-6 xl:border-b-0 xl:border-r"><h3 className="section-title">Scenario estimate</h3><p className="mt-1 text-sm leading-6 text-muted">Transparent arithmetic for a candidate control change. This does not execute traffic or predict recovery.</p>{([ ["retryCeiling","Retry ceiling",1,4,1,""], ["concurrencyCap","Concurrency cap",5,50,1," workers"], ["timeoutMs","Downstream timeout",500,5000,100,"ms"] ] as const).map(([key,label,min,max,step,suffix]) => <label key={key} className="mt-5 block text-sm font-semibold">{label}<span className="measurement-number float-right text-muted">{config[key]}{suffix}</span><input className="mt-3 h-2 w-full cursor-pointer accent-[oklch(var(--accent))]" type="range" min={min} max={max} step={step} value={config[key]} onChange={(event) => set(key, Number(event.target.value))} /></label>)}<button className="control-primary mt-6 inline-flex w-full items-center justify-center gap-2" disabled={run.isPending || !incident.events.length} onClick={() => run.mutate()}><GitCompare className="h-4 w-4" />{run.isPending ? "Saving estimate…" : dirty ? "Calculate candidate" : "Recalculate"}</button><MutationNote mutation={run as never} success="Scenario estimate saved against this evidence revision." /><div className="mt-6 border-t border-line pt-5"><h4 className="text-sm font-semibold">Saved estimates</h4><div className="mt-3 space-y-2">{history.data?.map((item) => <button key={item.id} className={cn("block w-full rounded-control p-3 text-left text-xs", selected?.id === item.id ? "bg-ink text-panel" : "bg-elevated text-muted hover:text-ink")} onClick={() => { setSelectedId(item.id); setConfig(item.config); }}><span className="font-semibold">{incident.service} control candidate</span><span className="mt-1 block opacity-70">{formatRelative(item.createdAt)} · {item.eventCount} evidence items</span></button>)}</div></div></div>
    <div className="p-5 sm:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="section-title">Candidate change review</h3><p className="mt-1 text-sm text-muted">Observed facts, assumptions, and the proposed action stay separate.</p></div>{selected && <span className="measurement-number rounded-full bg-elevated px-2.5 py-1 text-xs text-muted">{incident.service.toUpperCase()} · SAVED CANDIDATE</span>}</div>{selected ? <div className="mt-6"><div className="grid gap-4 sm:grid-cols-2"><div className="rounded-control bg-elevated p-4"><p className="text-xs text-muted">Recorded evidence peak</p><p className="measurement-number mt-1 text-xl font-semibold">{selected.projection.baselinePeak}/100 <span className="text-xs font-normal text-muted">heuristic severity</span></p></div><div className="rounded-control bg-elevated p-4"><p className="text-xs text-muted">Arithmetic candidate</p><p className="measurement-number mt-1 text-xl font-semibold">{selected.projection.projectedPeak}/100 <span className="text-xs font-normal text-muted">not measured</span></p></div></div><p className="mt-5 text-sm leading-6">{selected.projection.summary}</p>{selected.projection.unsupportedReasons?.length ? <div className="mt-4 rounded-control bg-warning/10 p-4"><p className="text-sm font-semibold text-warning">Not applicable yet</p><ul className="mt-2 space-y-1 text-xs text-muted">{selected.projection.unsupportedReasons.map((reason) => <li key={reason}>• {reason}</li>)}</ul></div> : <><div className="mt-5"><p className="text-xs font-semibold uppercase tracking-[.12em] text-muted">Assumptions</p><ul className="mt-2 space-y-2">{selected.projection.assumptions?.map((assumption) => <li key={assumption} className="flex gap-2 text-sm text-muted"><Check className="mt-0.5 h-4 w-4 shrink-0 text-info" />{assumption}</li>)}</ul></div><div className="mt-6 rounded-control bg-elevated p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><h4 className="text-sm font-semibold">Independent production review</h4><p className="mt-1 text-xs leading-5 text-muted">Review is bound to this exact candidate and evidence revision. It authorizes a bounded action, not the estimate itself.</p>{dirty && <p className="mt-2 text-xs font-semibold text-warning">Controls changed. Recalculate before requesting review.</p>}{stale && <p className="mt-2 text-xs font-semibold text-danger">Evidence changed. Recalculate this candidate.</p>}{workspace.data?.role === "viewer" && <p className="mt-2 text-xs font-semibold text-warning">Viewer access is read-only. Ask a responder or administrator to request review.</p>}</div><button className="control-primary" disabled={dirty || stale || requestApproval.isPending || workspace.data?.role === "viewer"} onClick={() => requestApproval.mutate()}><ShieldCheck className="mr-2 h-4 w-4" />Request review</button></div><MutationNote mutation={requestApproval as never} success="Review request created." /></div></>}
      </div> : <div className="py-14 text-center"><RotateCcw className="mx-auto h-6 w-6 text-faint" /><p className="mt-3 font-semibold">No candidate saved</p><p className="mt-1 text-sm text-muted">Calculate a scenario only when the controls apply to this failure mode.</p></div>}
      {approvals.data?.length ? <div className="mt-6 border-t border-line pt-5"><div className="flex flex-wrap items-center justify-between gap-2"><h4 className="text-sm font-semibold">Mitigation reviews</h4><span className="rounded-full bg-panel px-2.5 py-1 text-xs font-semibold capitalize text-muted">Signed in as {workspace.data?.role ?? "checking role"}</span></div><div className="mt-3 space-y-3">{approvals.data.map((item) => {
        const self = item.requestedBy.trim().toLowerCase() === user?.email.trim().toLowerCase();
        const admin = workspace.data?.role === "admin";
        const canApprove = admin && !self && !item.stale;
        const canReject = admin && !self;
        const canWithdraw = self && (workspace.data?.role === "admin" || workspace.data?.role === "responder");
        return <article id={`approval-${item.id}`} key={item.id} className="rounded-control bg-elevated p-4"><div className="flex justify-between gap-3"><div><p className="text-sm font-semibold">{item.title}</p><p className="mt-1 text-xs leading-5 text-muted">{item.action}</p><dl className="mt-3 grid gap-2 text-xs sm:grid-cols-2"><div><dt className="text-muted">Current</dt><dd className="font-semibold">{item.currentValue}</dd></div><div><dt className="text-muted">Proposed</dt><dd className="font-semibold">{item.proposedValue}</dd></div><div><dt className="text-muted">Blast radius</dt><dd>{item.blastRadius}</dd></div><div><dt className="text-muted">Owner / observation</dt><dd>{item.changeOwner} · {item.observationMinutes}m</dd></div></dl><p className="mt-2 text-xs text-muted">Rollback: {item.rollbackPlan}</p><p className="mt-1 text-xs text-muted">Requested by {item.requestedBy}. Policy requires a different workspace administrator to approve.</p>{item.stale && <p className="mt-2 text-xs font-semibold text-danger">Stale: evidence changed after this estimate. It cannot be approved.</p>}</div><span className={cn("h-fit rounded-full px-2.5 py-1 text-xs font-semibold capitalize", item.status === "approved" ? "bg-success/12 text-success" : item.status === "rejected" ? "bg-danger/10 text-danger" : "bg-warning/12 text-warning")}>{item.status}</span></div>{item.status === "pending" && <div className="mt-3 border-t border-line pt-3"><p className="text-xs leading-5 text-muted">{self ? "You requested this change. Another administrator must approve it; you can withdraw it." : admin ? item.stale ? "This candidate must be recalculated. You may reject it to clear the pending request." : "You are the independent administrator for this review." : "Only a workspace administrator can approve or reject another person’s request."}</p><div className="mt-2 flex flex-wrap gap-2">{canApprove && <button className="control-secondary !min-h-9" disabled={review.isPending} onClick={() => review.mutate({ id:item.id, status:"approved" })}>Approve exact change</button>}{canReject && <button className="control-quiet !min-h-9 text-danger" disabled={review.isPending} onClick={() => review.mutate({ id:item.id, status:"rejected" })}>Reject</button>}{canWithdraw && <button className="control-quiet !min-h-9 text-danger" disabled={review.isPending} onClick={() => review.mutate({ id:item.id, status:"rejected" })}>Withdraw request</button>}</div></div>}</article>;
      })}</div><MutationNote mutation={review as never} success="Review decision recorded in the audit trail." /></div> : null}
    </div></section>;
}

type HttpReplayDraft = { name:string; applicationVersion:string; method:HttpReplaySpec["request"]["method"]; path:string; body:string; expectedStatus:string; bodyIncludes:string; dependencyName:string; dependencyFixture:string };
function HttpReplayPanel({ incident }: { incident: Incident }) {
  const client=useQueryClient();
  const initial:HttpReplayDraft={name:"",applicationVersion:"",method:"POST",path:"/",body:"",expectedStatus:"200",bodyIncludes:"",dependencyName:"external-api",dependencyFixture:"disabled"};
  const draft=usePersistentDraft(`replayops:${incident.id}:http-replay`,initial);
  const history=useQuery({queryKey:["http-replays",incident.id],queryFn:()=>api.httpReplays(incident.id)});
  const set=(key:keyof HttpReplayDraft,value:string)=>draft.setValue((current)=>({...current,[key]:value}));
  const create=useMutation({mutationFn:()=>api.createHttpReplay(incident.id,{name:draft.value.name,applicationVersion:draft.value.applicationVersion,request:{method:draft.value.method,path:draft.value.path,headers:{"content-type":"application/json"},...(draft.value.body?{body:draft.value.body}:{})},assertions:{status:Number(draft.value.expectedStatus),...(draft.value.bodyIncludes?{bodyIncludes:draft.value.bodyIncludes}:{})},dependencies:[{name:draft.value.dependencyName,mode:"mocked",fixture:draft.value.dependencyFixture}]}),onSuccess:(value)=>{client.setQueryData<{specs:HttpReplaySpec[];executions:HttpReplayExecution[]}>(["http-replays",incident.id],(current)=>({specs:[value,...(current?.specs??[])],executions:current?.executions??[]}));draft.clear();}});
  const execute=useMutation({mutationFn:(id:string)=>api.executeHttpReplay(id),onSuccess:(value)=>{client.setQueryData<{specs:HttpReplaySpec[];executions:HttpReplayExecution[]}>(["http-replays",incident.id],(current)=>({specs:current?.specs??[],executions:[value,...(current?.executions??[])]}));void api.recordProductOutcome("replay_executed",{incidentId:incident.id,status:value.status,nondeterministic:value.nondeterministic});}});
  const latestFor=(id:string)=>history.data?.executions.find((item)=>item.specId===id);
  return <section className="border-t border-line"><div className="grid xl:grid-cols-[minmax(330px,.78fr)_minmax(0,1.22fr)]"><form className="border-b border-line bg-rail p-5 sm:p-6 xl:border-b-0 xl:border-r" onSubmit={(event)=>{event.preventDefault();create.mutate();}}><div className="flex items-center gap-2"><RotateCcw className="h-4 w-4 text-info"/><h3 className="section-title">Bounded HTTP replay</h3></div><p className="mt-1 text-sm leading-6 text-muted">Capture one HTTP failure with explicit assertions and mocked dependencies. Execution is restricted to a loopback target in local or CI environments.</p><label className="mt-4 block text-sm font-semibold">Replay name<input className="field mt-2" value={draft.value.name} onChange={(event)=>set("name",event.target.value)} placeholder="Checkout rejects expired reservation" required minLength={4}/></label><div className="mt-4 grid grid-cols-[120px_1fr] gap-3"><label className="text-sm font-semibold">Method<select className="field mt-2" value={draft.value.method} onChange={(event)=>set("method",event.target.value)}>{["GET","POST","PUT","PATCH","DELETE"].map((item)=><option key={item}>{item}</option>)}</select></label><label className="text-sm font-semibold">Request path<input className="field mt-2" value={draft.value.path} onChange={(event)=>set("path",event.target.value)} placeholder="/api/checkout" required pattern="/.*"/></label></div><label className="mt-4 block text-sm font-semibold">Application / code version<input className="field mt-2" value={draft.value.applicationVersion} onChange={(event)=>set("applicationVersion",event.target.value)} placeholder="git SHA or image digest" required/></label><label className="mt-4 block text-sm font-semibold">Redacted request body<textarea className="field mt-2 min-h-20 resize-y py-3 font-mono text-xs" value={draft.value.body} onChange={(event)=>set("body",event.target.value)} placeholder='{"reservationId":"fixture-123"}'/></label><div className="mt-4 grid grid-cols-2 gap-3"><label className="text-sm font-semibold">Expected status<input className="field mt-2" type="number" min="100" max="599" value={draft.value.expectedStatus} onChange={(event)=>set("expectedStatus",event.target.value)} required/></label><label className="text-sm font-semibold">Body must include<input className="field mt-2" value={draft.value.bodyIncludes} onChange={(event)=>set("bodyIncludes",event.target.value)} placeholder="order confirmed"/></label></div><label className="mt-4 block text-sm font-semibold">Mocked dependency fixture<textarea className="field mt-2 min-h-16 resize-y py-3 font-mono text-xs" value={draft.value.dependencyFixture} onChange={(event)=>set("dependencyFixture",event.target.value)} required/></label><button className="control-primary mt-4 w-full" disabled={create.isPending}>Save immutable replay</button><MutationNote mutation={create as never} success="Replay capture saved against this evidence revision."/></form><div className="p-5 sm:p-6"><h3 className="section-title">Execution history</h3><p className="mt-1 text-sm text-muted">Each run sends the same request twice to detect nondeterminism. Public hosting does not receive production credentials or unrestricted network access.</p><div className="mt-5 space-y-3">{history.data?.specs.map((spec)=>{const result=latestFor(spec.id);const stale=spec.evidenceRevision!==(incident.evidenceRevision??incident.updatedAt);return <article key={spec.id} className="rounded-control bg-elevated p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm font-semibold">{spec.name}</p><p className="measurement-number mt-1 text-xs text-muted">{spec.request.method} {spec.request.path} · version {spec.applicationVersion}</p><p className="mt-1 text-xs text-muted">Assertions: status {spec.assertions.status}{spec.assertions.bodyIncludes?` · body includes “${spec.assertions.bodyIncludes}”`:""}</p></div>{result?<span className={cn("rounded-full px-2.5 py-1 text-xs font-semibold capitalize",result.status==="passed"?"bg-success/12 text-success":result.status==="unsupported"?"bg-warning/12 text-warning":"bg-danger/10 text-danger")}>{result.status}</span>:<span className="rounded-full bg-panel px-2.5 py-1 text-xs font-semibold">not run</span>}</div>{result?.assertionResults.map((item)=><p key={item.assertion} className={cn("mt-2 text-xs",item.passed?"text-success":"text-danger")}>{item.passed?"✓":"×"} {item.assertion} · observed {item.observed}</p>)}{result?.limitation&&<p className="mt-2 text-xs leading-5 text-warning">{result.limitation}</p>}{result?.nondeterministic&&<p className="mt-2 text-xs font-semibold text-danger">Nondeterministic output detected across identical runs.</p>}<div className="mt-3 flex flex-wrap items-center gap-2"><button className="control-secondary !min-h-9" disabled={stale||execute.isPending} onClick={()=>execute.mutate(spec.id)}>Execute isolated replay</button><button className="control-quiet !min-h-9" onClick={()=>{const manifest={schemaVersion:"replayops.http-replay/v1",...spec};const url=URL.createObjectURL(new Blob([JSON.stringify(manifest,null,2)],{type:"application/json"}));const link=document.createElement("a");link.href=url;link.download=`replay-${spec.id}.json`;link.click();URL.revokeObjectURL(url);}}>Download CI manifest</button>{stale&&<span className="text-xs font-semibold text-danger">Evidence changed; capture a new replay.</span>}</div></article>;})}{history.data&&!history.data.specs.length&&<div className="py-12 text-center text-sm text-muted">No replayable HTTP request captured.</div>}</div><MutationNote mutation={execute as never} success="Execution result preserved with inputs, outputs, and evidence revision."/></div></div></section>;
}

type RecoveryDraft = { metric: string; unit: string; comparison: "lte" | "gte"; baselineValue: string; targetValue: string; observedValue: string; observationMinutes: string; source: string; query: string; windowStartedAt: string; windowEndedAt: string; observedAt: string; reason: string };
function RecoveryPanel({ incident }: { incident: Incident }) {
  const client = useQueryClient();
  const initial: RecoveryDraft = { metric: "", unit: "%", comparison: "lte", baselineValue: "", targetValue: "", observedValue: "", observationMinutes: "15", source: "", query: "", windowStartedAt: "", windowEndedAt: "", observedAt: "", reason: "" };
  const draft = usePersistentDraft(`replayops:${incident.id}:recovery`, initial);
  const recoveries = useQuery({ queryKey: ["recoveries", incident.id], queryFn: () => api.recoveries(incident.id) });
  const set = (key: keyof RecoveryDraft, value: string) => draft.setValue((current) => ({ ...current, [key]: value }));
  const save = useMutation({ mutationFn: () => api.saveRecovery(incident.id, { metric: draft.value.metric, unit: draft.value.unit, comparison: draft.value.comparison, baselineValue: Number(draft.value.baselineValue), targetValue: Number(draft.value.targetValue), observedValue: Number(draft.value.observedValue), observationMinutes: Number(draft.value.observationMinutes), source: draft.value.source, query: draft.value.query, windowStartedAt: new Date(draft.value.windowStartedAt).toISOString(), windowEndedAt: new Date(draft.value.windowEndedAt).toISOString(), observedAt: new Date(draft.value.observedAt).toISOString(), reason: draft.value.reason }), onSuccess: (value) => { client.setQueryData<RecoveryVerification[]>(["recoveries", incident.id], (current) => [value, ...(current ?? [])]); if(value.status==="verified")void api.recordProductOutcome("recovery_verified",{incidentId:incident.id,recoveryId:value.id}); draft.clear(); } });
  const complete = draft.value.metric && draft.value.baselineValue && draft.value.targetValue && draft.value.observedValue && draft.value.source && draft.value.windowStartedAt && draft.value.windowEndedAt && draft.value.observedAt && draft.value.reason.length >= 8;
  return <section className="grid lg:grid-cols-[minmax(320px,.82fr)_minmax(0,1.18fr)]"><form className="border-b border-line bg-rail p-5 sm:p-6 lg:border-b-0 lg:border-r" onSubmit={(event) => { event.preventDefault(); save.mutate(); }}><h3 className="section-title">Verify actual recovery</h3><p className="mt-1 text-sm leading-6 text-muted">Record a real observation. The server checks direction and freshness; the newest failure overrides an older pass.</p><label className="mt-5 block text-sm font-semibold">Metric<input className="field mt-2" value={draft.value.metric} onChange={(event) => set("metric", event.target.value)} placeholder="HTTP 5xx rate" required /></label><div className="mt-4 grid grid-cols-2 gap-4"><label className="text-sm font-semibold">Unit<input className="field mt-2" value={draft.value.unit} onChange={(event) => set("unit", event.target.value)} placeholder="%" required /></label><label className="text-sm font-semibold">Healthy when<select className="field mt-2" value={draft.value.comparison} onChange={(event) => set("comparison", event.target.value as "lte" | "gte")}><option value="lte">At or below target</option><option value="gte">At or above target</option></select></label><label className="text-sm font-semibold">Baseline<input className="field mt-2" type="number" step="any" value={draft.value.baselineValue} onChange={(event) => set("baselineValue", event.target.value)} required /></label><label className="text-sm font-semibold">Target<input className="field mt-2" type="number" step="any" value={draft.value.targetValue} onChange={(event) => set("targetValue", event.target.value)} required /></label><label className="text-sm font-semibold">Observed<input className="field mt-2" type="number" step="any" value={draft.value.observedValue} onChange={(event) => set("observedValue", event.target.value)} required /></label><label className="text-sm font-semibold">Window minutes<input className="field mt-2" type="number" min="1" max="10080" value={draft.value.observationMinutes} onChange={(event) => set("observationMinutes", event.target.value)} required /></label></div><label className="mt-4 block text-sm font-semibold">Source<input className="field mt-2" value={draft.value.source} onChange={(event) => set("source", event.target.value)} placeholder="Grafana / Prometheus / SQL" required /></label><label className="mt-4 block text-sm font-semibold">Query or source link<input className="field mt-2" value={draft.value.query} onChange={(event) => set("query", event.target.value)} placeholder={'sum(rate(http_requests_total{status=~"5.."}[5m]))'} /></label><div className="mt-4 grid gap-4 sm:grid-cols-3"><label className="text-sm font-semibold">Window start<input className="field mt-2" type="datetime-local" value={draft.value.windowStartedAt} onChange={(event) => set("windowStartedAt", event.target.value)} required /></label><label className="text-sm font-semibold">Window end<input className="field mt-2" type="datetime-local" value={draft.value.windowEndedAt} onChange={(event) => set("windowEndedAt", event.target.value)} required /></label><label className="text-sm font-semibold">Observed at<input className="field mt-2" type="datetime-local" value={draft.value.observedAt} onChange={(event) => set("observedAt", event.target.value)} required /></label></div><label className="mt-4 block text-sm font-semibold">Why this measurement is sufficient<textarea className="field mt-2 min-h-20 resize-y py-3" value={draft.value.reason} onChange={(event) => set("reason", event.target.value)} required minLength={8} /></label><p className="mt-3 text-xs text-muted">{draft.savedAt ? `Draft saved ${formatRelative(draft.savedAt)}` : "Blank by design—no recovery is assumed."}</p><button className="control-primary mt-4 w-full" disabled={!complete || save.isPending}>Record measured observation</button><MutationNote mutation={save as never} success="Observation saved; recovery state was derived server-side." /></form>
    <div className="p-5 sm:p-6"><h3 className="section-title">Recovery history</h3><p className="mt-1 text-sm text-muted">Resolution uses the latest observation, not the best historical result.</p><div className="mt-5 space-y-3">{recoveries.data?.map((item, index) => <article key={item.id} className="rounded-control bg-elevated p-4"><div className="flex justify-between gap-3"><div><p className="text-sm font-semibold">{item.metric}{index === 0 ? " · latest" : ""}</p><p className="mt-1 text-xs text-muted">{item.source} · observed {item.observedAt ? formatRelative(item.observedAt) : "time unknown"}</p></div><span className={cn("h-fit rounded-full px-2.5 py-1 text-xs font-semibold capitalize", item.status === "verified" ? "bg-success/12 text-success" : item.status === "pending" ? "bg-warning/12 text-warning" : "bg-danger/10 text-danger")}>{item.status}</span></div><p className="measurement-number mt-3 text-sm">{item.baselineValue}{item.unit} baseline → {item.observedValue ?? "—"}{item.unit} observed · target {item.comparison === "gte" ? "≥" : "≤"} {item.targetValue}{item.unit}</p><p className="mt-2 text-xs leading-5 text-muted">{item.observationMinutes} minute window · freshness {item.freshnessMinutes ?? "?"}m · {item.reason}</p>{item.query && (/^https?:/.test(item.query) ? <a href={item.query} target="_blank" rel="noreferrer" className="mt-2 inline-flex items-center gap-1 text-xs font-semibold text-info hover:underline">Open measurement <ExternalLink className="h-3 w-3" /></a> : <code className="mt-2 block overflow-x-auto rounded bg-panel p-2 text-xs">{item.query}</code>)}</article>)}{recoveries.data && !recoveries.data.length && <div className="py-12 text-center text-sm text-muted">No measured recovery observation.</div>}</div></div></section>;
}

function buildHandoff(incident: Incident, diagnosis: IncidentDiagnosis | undefined, decisions: IncidentDecision[], replay: ReplayResult | null, tests: HypothesisTest[], recovery: RecoveryVerification | null) {
  const known = incident.events.filter((event) => event.evidenceState !== "excluded");
  const unknowns = diagnosis?.evidenceGaps ?? [];
  return `# ${incident.code} handoff — ${incident.title}\n\nStatus: ${incident.status} · Severity: ${incident.severity} · Owner: ${incident.owner}\nService: ${incident.service} · Environment: ${incident.environment ?? "unknown"}\nEvidence revision: ${incident.evidenceRevision ?? incident.updatedAt}\n\n## Customer symptom and impact\n${incident.customerImpact || incident.summary || "Impact is not yet measured."}\n\n## Current explanation\n${diagnosis?.currentExplanation ?? "No evidence-grounded explanation yet."}\n\n## What we know\n${known.length ? known.map((event) => `- [${event.title}](#event-${event.id}) — ${event.detail} (${event.service}, ${event.timestamp})`).join("\n") : "- No active evidence."}\n\n## Unknown / missing\n${unknowns.length ? unknowns.map((item) => `- ${item}`).join("\n") : "- No explicit gaps recorded."}\n\n## Tests tried\n${tests.length ? tests.map((test) => `- ${test.title} — ${test.status}${test.result ? `: ${test.result}` : ""}`).join("\n") : "- No structured tests."}\n\n## Ruled out\n${tests.filter((test) => test.status === "disproved").length ? tests.filter((test) => test.status === "disproved").map((test) => `- ${test.title}: ${test.result}`).join("\n") : "- Nothing ruled out yet."}\n\n## Reviewed decisions\n${decisions.length ? decisions.map((item) => `- ${item.title} — ${item.status}: ${item.detail}`).join("\n") : "- No manual notes."}\n\n## Candidate validation\n${replay ? `${replay.projection.summary} Saved as ${replay.id}; this is a scenario estimate unless an executed replay record says otherwise.` : "No scenario or executed replay."}\n\n## Recovery\n${recovery ? `${recovery.metric}: ${recovery.observedValue}${recovery.unit} against target ${recovery.comparison === "gte" ? "≥" : "≤"} ${recovery.targetValue}${recovery.unit}; ${recovery.status}. Source: ${recovery.source}.` : "No measured recovery."}\n\n## Next action\n${diagnosis?.nextAction.label ?? "Acquire the missing evidence."} — ${diagnosis?.nextAction.reason ?? "No next action derived."}\n`;
}

function HandoffBrief({ incident }: { incident: Incident }) {
  const client = useQueryClient();
  const decisions = useQuery({ queryKey: ["decisions", incident.id], queryFn: () => api.decisions(incident.id) });
  const diagnosis = useQuery({ queryKey: ["diagnosis", incident.id, incident.evidenceRevision], queryFn: () => api.diagnosis(incident.id) });
  const replays = useQuery({ queryKey: ["replays", incident.id], queryFn: () => api.replays(incident.id) });
  const tests = useQuery({ queryKey: ["hypothesis-tests", incident.id], queryFn: () => api.hypothesisTests(incident.id) });
  const recoveries = useQuery({ queryKey: ["recoveries", incident.id], queryFn: () => api.recoveries(incident.id) });
  const postmortem = useQuery({ queryKey: ["postmortem", incident.id], queryFn: () => api.postmortem(incident.id) });
  const comments=useQuery({queryKey:["comments",incident.id],queryFn:()=>api.comments(incident.id)});
  const services=useQuery({queryKey:["services"],queryFn:api.services});
  const initial = { summary: incident.summary, rootCause: "", impact: incident.customerImpact ?? "", recovery: "", followUps: "", status: "draft" as const };
  const local = usePersistentDraft<Omit<IncidentPostmortem,"incidentId"|"updatedAt">>(`replayops:${incident.id}:postmortem`, initial);
  const [copied, setCopied] = useState(false);
  const [comment,setComment]=useState("");const [eventId,setEventId]=useState("");
  useEffect(() => { if (postmortem.data && !local.savedAt) local.setValue({ summary: postmortem.data.summary, rootCause: postmortem.data.rootCause, impact: postmortem.data.impact, recovery: postmortem.data.recovery, followUps: postmortem.data.followUps, status: postmortem.data.status }); }, [postmortem.data]);
  const save = useMutation({ mutationFn: (status: "draft"|"published") => api.savePostmortem(incident.id, { ...local.value, status }), onSuccess: (value) => { client.setQueryData(["postmortem", incident.id], value); local.clear(); } });
  const addComment=useMutation({mutationFn:()=>api.createComment(incident.id,{body:comment,eventId:eventId||null}),onSuccess:(value)=>{client.setQueryData<IncidentComment[]>(["comments",incident.id],(current)=>[...(current??[]),value]);setComment("");setEventId("");}});
  const brief = useMemo(() => buildHandoff(incident, diagnosis.data, decisions.data ?? [], replays.data?.[0] ?? null, tests.data ?? [], recoveries.data?.[0] ?? null), [incident, diagnosis.data, decisions.data, replays.data, tests.data, recoveries.data]);
  const update = (key: keyof typeof local.value, value: string) => local.setValue((current) => ({ ...current, [key]: value }));
  const service=services.data?.find((item)=>item.name===incident.service);const issueUrl=service?.repositoryUrl?`${service.repositoryUrl.replace(/\/$/,"")}/issues/new?title=${encodeURIComponent(`[${incident.code}] ${incident.title}`)}&body=${encodeURIComponent(brief.slice(0,6000))}`:undefined;
  return <div className="grid lg:grid-cols-[minmax(320px,.82fr)_minmax(0,1.18fr)]"><div className="border-b border-line bg-rail p-5 sm:p-6 lg:border-b-0 lg:border-r"><h3 className="section-title">Learning record</h3><p className="mt-1 text-sm leading-6 text-muted">Unknown root cause is valid. Preserve what was tried and assign follow-ups with owner, date, and status.</p>{([ ["summary","Executive summary"], ["rootCause","Validated cause or unresolved explanation"], ["impact","Measured impact and unknown denominators"], ["recovery","Recovery measurement"], ["followUps","Follow-ups — owner · due date · status"] ] as const).map(([key,label]) => <label key={key} className="mt-4 block text-sm font-semibold">{label}<textarea className="field mt-2 min-h-20 resize-y py-3" value={local.value[key]} onChange={(event) => update(key, event.target.value)} /></label>)}<p className="mt-3 text-xs text-muted">{local.savedAt ? `Draft saved ${formatRelative(local.savedAt)}` : "Draft autosaves on this device."}</p><div className="mt-4 flex flex-wrap gap-2"><button className="control-secondary" onClick={() => save.mutate("draft")}>Save draft</button><button className="control-primary" onClick={() => save.mutate("published")}>Publish learning record</button></div><MutationNote mutation={save as never} success="Learning record saved." /></div><div className="p-5 sm:p-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h3 className="section-title">Shift handoff</h3><p className="mt-1 text-xs text-muted">Known, unknown, tried, ruled out, recovery, and exact source anchors.</p></div><div className="flex flex-wrap gap-2">{issueUrl&&<a className="control-secondary !min-h-9" href={issueUrl} target="_blank" rel="noreferrer"><ExternalLink className="mr-2 h-4 w-4"/>Open issue draft</a>}<button className="control-secondary !min-h-9" onClick={async () => { await navigator.clipboard.writeText(brief); setCopied(true); }}><ClipboardCopy className="mr-2 h-4 w-4" />{copied ? "Copied" : "Copy"}</button><button className="control-secondary !min-h-9" onClick={() => { const url = URL.createObjectURL(new Blob([brief], { type:"text/markdown" })); const link = document.createElement("a"); link.href=url; link.download=`${incident.code.toLowerCase()}-handoff.md`; link.click(); URL.revokeObjectURL(url); }}><Download className="mr-2 h-4 w-4" />.md</button></div></div><pre className="measurement-number mt-5 max-h-[560px] overflow-auto whitespace-pre-wrap rounded-control bg-elevated p-4 text-xs leading-6">{brief}</pre><div className="mt-6 border-t border-line pt-5"><div className="flex items-center gap-2"><MessageSquare className="h-4 w-4 text-info"/><h3 className="section-title">Evidence-linked collaboration</h3></div><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_190px_auto]"><input className="field" value={comment} onChange={(event)=>setComment(event.target.value)} placeholder="@mention a responder and state the question"/><select className="field" value={eventId} onChange={(event)=>setEventId(event.target.value)}><option value="">General investigation</option>{incident.events.map((event)=><option key={event.id} value={event.id}>{event.title.slice(0,42)}</option>)}</select><button className="control-primary" disabled={comment.trim().length<2||addComment.isPending} onClick={()=>addComment.mutate()}>Comment</button></div><div className="mt-4 space-y-2">{comments.data?.map((item)=><article key={item.id} className="rounded-control bg-elevated p-3"><p className="text-sm leading-6">{item.body}</p><p className="mt-1 text-xs text-muted">{item.actor} · {formatRelative(item.createdAt)}{item.eventId&&<> · <a className="font-semibold text-info hover:underline" href={`?area=investigate&event=${item.eventId}#event-${item.eventId}`}>source evidence</a></>}</p></article>)}</div></div></div></div>;
}

export function ResponseConsole({ incident }: { incident: Incident }) {
  const [params, setParams] = useSearchParams();
  const requested = params.get("area");
  const area: WorkArea = requested === "validate" || requested === "handoff" ? requested : "investigate";
  const setArea = (next: WorkArea) => { const copy = new URLSearchParams(params); copy.set("area", next); setParams(copy, { replace: true }); };
  const openTest = (testId: string) => { const copy = new URLSearchParams(params); copy.set("area", "investigate"); copy.set("test", testId); setParams(copy, { replace: true }); window.setTimeout(() => document.getElementById(`test-${testId}`)?.scrollIntoView({ behavior:"smooth", block:"center" }), 80); };
  return <section id="investigation-workspace" className="surface scroll-mt-28 overflow-hidden" aria-labelledby="response-console-title"><div className="flex flex-col gap-4 px-5 py-5 sm:px-6 lg:flex-row lg:items-center lg:justify-between"><div><h2 id="response-console-title" className="font-heading text-xl font-semibold tracking-[-.025em]">Investigation workspace</h2><p className="mt-1 max-w-2xl text-sm leading-6 text-muted">Inspect evidence, falsify explanations, validate a bounded change, and prove real recovery.</p></div><div className="flex overflow-x-auto rounded-control bg-rail p-1" role="tablist">{areas.map((item) => <button key={item.id} role="tab" aria-selected={area === item.id} className={cn("flex min-h-10 shrink-0 items-center gap-2 rounded-[8px] px-3 text-xs font-semibold transition-colors sm:text-sm", area === item.id ? "bg-ink text-panel" : "text-muted hover:bg-elevated hover:text-ink")} onClick={() => setArea(item.id)}><item.icon className="h-4 w-4" />{item.label}</button>)}</div></div><div className="border-t border-line"><AnimatePresence mode="wait" initial={false}><motion.div key={area} role="tabpanel" initial={{ opacity:.65, y:4 }} animate={{ opacity:1, y:0 }} exit={{ opacity:0, y:-3 }} transition={{ duration:.16 }}>{area === "investigate" ? <InvestigationPanel incident={incident} onOpenTest={openTest} /> : area === "validate" ? <div><ScenarioEstimate incident={incident} /><HttpReplayPanel incident={incident}/><div className="border-t border-line"><RecoveryPanel incident={incident} /></div></div> : <HandoffBrief incident={incident} />}</motion.div></AnimatePresence></div></section>;
}
